SELECT dataTable.warning_type_id typeId,dataTable.warning_type_name as typeName,
date_format(dataTable.create_date,'%Y-%m-%d') createDate,SUM(dataTable.warning_num) num
FROM vm_statistics_event_type dataTable
WHERE 1 = 1
${dataScope}
AND dataTable.create_date >= #{queryStartTime}
AND dataTable.create_date <= #{queryEndTime}

    AND dataTable.warning_type_id IN

        #{labelIdItem}



    AND (dataTable.county_id = #{countyId} or dataTable.province_id = #{countyId} or dataTable.city_id = #{countyId})

GROUP BY dataTable.warning_type_id,date_format(dataTable.create_date,'%Y-%m-%d')

    UNION
    SELECT "aaa666" typeId,"其他" typeName,date_format(dataTable.create_date,'%Y-%m-%d') createDate,SUM(dataTable.warning_num) num
    FROM vm_statistics_event_type dataTable
    WHERE 1 = 1
    ${dataScope}
    AND dataTable.create_date >= #{queryStartTime}
    AND dataTable.create_date <= #{queryEndTime}

        AND dataTable.warning_type_id NOT IN

            #{labelIdItem}



        AND (dataTable.county_id = #{countyId} or dataTable.province_id = #{countyId} or dataTable.city_id = #{countyId})

    GROUP BY date_format(dataTable.create_date,'%Y-%m-%d')

SELECT SUM(dataTable.less_one) AS lessOneHour,SUM(dataTable.one_five) AS oneFiveHour,
SUM(dataTable.five_ten) AS fiveTenHour,SUM(dataTable.more_ten) AS overTenHour
FROM vm_statistics_event_duration dataTable


        AND LEFT(dataTable.county_id,2) = LEFT(#{provinceId},2)


        AND LEFT(dataTable.county_id,4) = LEFT(#{cityId},4)


        AND (dataTable.county_id = #{countyId} or dataTable.province_id = #{countyId} or dataTable.city_id = #{countyId})


        AND dataTable.create_date >= #{queryStartTime}
        AND dataTable.create_date <= #{queryEndTime}

    ${dataScope}

SELECT region_name AS regionName, round(sum(handle_duration)/3600/sum(duration_num),2) AS avgTime, province_id AS provinceId, city_id AS cityId, county_id AS countyId FROM vm_statistics_event_handle dataTable
AND create_date >= #{queryStartTime} AND create_date <= #{queryEndTime}
AND province_id = #{provinceId}
AND city_id = #{cityId}
AND (dataTable.county_id = #{countyId} or dataTable.province_id = #{countyId} or dataTable.city_id = #{countyId})
${dataScope}
GROUP BY province_id, city_id, county_id order by avgTime desc

SELECT channelCode,channelName,deviceCode,deviceName,SUM(foreAlgorithmTaskNum) as foreAlgorithmTaskNum ,SUM(startForeAlgorithmTaskNum) as startForeAlgorithmTaskNum,SUM(afterAlgorithmTaskNum) as afterAlgorithmTaskNum,SUM(startAfterAlgorithmTaskNum) as startAfterAlgorithmTaskNum, SUM( foreAlgorithmTaskNum )+SUM( afterAlgorithmTaskNum ) AS taskNum, SUM( startForeAlgorithmTaskNum )+SUM( startAfterAlgorithmTaskNum ) AS strTaskNum FROM ( SELECT IFNULL(b.channel_name,c.channel_name) as channelName,IFNULL(b.device_name,od.device_name) as deviceName,COUNT(1) AS foreAlgorithmTaskNum,COUNT(IF(dataTable.`status` = '0', 1, NULL)) AS startForeAlgorithmTaskNum,0 AS afterAlgorithmTaskNum,0 AS startAfterAlgorithmTaskNum, od.device_code as deviceCode,c.channel_code as channelCode FROM `vm_algorithm_give_config` dataTable left join vm_device_info_t t on t.device_code = dataTable.device_code left JOIN vm_order_devices od ON od.device_code = t.device_code and od.tenant_id = dataTable.tenant_id AND dataTable.industry_code = od.industry_code left join vm_channel_info_t c on t.device_code = c.device_code and c.channel_code = dataTable.channel_code left join vm_tenant_device_channel_rel_t b on b.device_code = od.device_code AND b.channel_code = c.channel_code AND b.industry_code = od.industry_code AND b.tenant_id = od.tenant_id AND b.delete_flag='0' where dataTable.delete_flag = '0' and od.delete_flag = '0' and od.ord_status IN (0, 1, 2) and t.delete_flag = '0' and c.delete_flag = '0'
and dataTable.device_code in
#{item}
and ( t.province_id in
#{item}
or t.city_id in
#{item}
or t.county_id in
#{item}
or t.town_code in
#{item}
)
${dataScope} GROUP BY dataTable.channel_code UNION ALL SELECT IFNULL(b.channel_name,c.channel_name) as channelName, IFNULL(b.device_name,od.device_name) as deviceName,0 AS foreAlgorithmTaskNum,0 AS startForeAlgorithmTaskNum,COUNT(1) AS afterAlgorithmTaskNum,COUNT(IF(dataTable.`status` = '0', 1, NULL)) AS startAfterAlgorithmTaskNum, od.device_code as deviceCode,c.channel_code as channelCode FROM `vm_algorithm_config` dataTable left join vm_device_info_t t on t.device_code = dataTable.device_code left JOIN vm_order_devices od ON od.device_code = t.device_code and od.tenant_id = dataTable.tenant_id AND dataTable.industry_code = od.industry_code left join vm_channel_info_t c on t.device_code = c.device_code and c.channel_code = dataTable.channel_code left join vm_tenant_device_channel_rel_t b on b.device_code = od.device_code AND b.channel_code = c.channel_code AND b.industry_code = od.industry_code AND b.delete_flag='0' AND b.tenant_id = od.tenant_id where dataTable.delete_flag = '0' and od.delete_flag = '0' and od.ord_status IN (0, 1, 2) and t.delete_flag = '0' and c.delete_flag = '0'
and dataTable.device_code in
#{item}
and ( t.province_id in
#{item}
or t.city_id in
#{item}
or t.county_id in
#{item}
or t.town_code in
#{item}
)
${dataScope} GROUP BY dataTable.channel_code )c GROUP BY channelCode ORDER BY deviceCode

SELECT DISTINCT dt.device_code
from sys_dept d LEFT JOIN vm_organ_device_rel_t dt ON d.DEPT_ID = dt.dept_id
left join vm_order_devices od on dt.device_code = od.device_code
WHERE od.delete_flag = '0' and od.ord_status IN (0, 1, 2) and dt.device_type NOT IN (8,9,10) AND od.tenant_id=#{tenantId} and od.industry_code=#{industryCode}

    and d.DEPT_ID in

        #{item}

