AND DATE_FORMAT(dataTable.login_time,'%Y-%m-%d') >= DATE_FORMAT(#{queryStartTime}, '%Y-%m-%d') AND DATE_FORMAT(dataTable.login_time,'%Y-%m-%d') <= DATE_FORMAT(#{queryEndTime}, '%Y-%m-%d')
AND(
(dataTable.dept_id = #{deptId} OR dataTable.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE INSTR(ANCESTORS, #{deptId})>0 ) )
)
${dataScope}
